Given the head of a linked list and an integer x, delete the node at position x and return the updated head of the linked list.Note: Positions use 1-based indexing.Examples:  Input: x = 4, Output: 1 -> 2 -> 3 -> 5Explanation: After deleting the node at the 4th position, the linked list is as Input: x = 6, Output: 2 -> 5 -> 7 -> 8 -> 99Explanation: After deleting the node at 6th position, the linked list is as Try It YourselfTable of Content[Naive Approach] Store Nodes in an Array - O(n) Time and O(n) Space[Expected Approach] Single Traversal Deletion - O(n) Time and O(1) Space[Naive Approach] Store Nodes in an Array - O(n) Time and O(n) SpaceThe idea is to traverse the linked list and store the address of every node in an array. This allows direct access to the node at position x. Then, update the links to remove the node and delete it.Working of Approach:Traverse the linked list and store all node pointers in an array.If x == 1, delete the head node.Otherwise, access the previous and current nodes using the array.Update the previous node's next pointer.Delete the node and return the updated head.
            C++

    #include <bits/stdc++.h>
using namespace std;

class Node
{
  public:
    int data;
    Node *next;
    Node(int x)
    {
        data = x;
        next = nullptr;
    }
};

Node *deleteNode(Node *head, int x)
{

    vector<Node *> nodes;

    // Store all node pointers
    Node *curr = head;
    while (curr != nullptr)
    {
        nodes.push_back(curr);
        curr = curr->next;
    }

    // Delete the head node
    if (x == 1)
    {
        Node *temp = head;
        head = head->next;
        delete temp;
        return head;
    }

    Node *prev = nodes[x - 2];
    Node *delNode = nodes[x - 1];

    // Remove the node
    prev->next = delNode->next;
    delete delNode;

    return head;
}

// Function to print the linked list
void printList(Node *head)
{
    while (head != nullptr)
    {
        cout << head->data;
        if (head->next)
            cout << " -> ";
        head = head->next;
    }
    cout << endl;
}

int main()
{

    // Create linked list:
    // 2 -> 5 -> 7 -> 8 -> 99 -> 100
    Node *head = new Node(2);
    head->next = new Node(5);
    head->next->next = new Node(7);
    head->next->next->next = new Node(8);
    head->next->next->next->next = new Node(99);
    head->next->next->next->next->next = new Node(100);

    int x = 6;

    head = deleteNode(head, x);

    printList(head);

    return 0;
}


